extern "C" __global__ void __cluster_dims__(4,1,1) __launch_bounds__(256) k32s4r(const __half* A, const __half* B, __half* C, int M){ body<32,4,1>(A,B,C,M); }
extern "C" __global__ void __cluster_dims__(8,1,1) __launch_bounds__(256) k64s8(const __half* A, const __half* B, __half* C, int M){ body<64,8,0>(A,B,C,M); }
extern "C" __global__ void __cluster_dims__(8,1,1) __launch_bounds__(256) k64s8r(const __half* A, const __half* B, __half* C, int M){ body<64,8,1>(A,B,C,M); }
'''
res = bp.resources(SRC)
print(res)
s = bp.sass(SRC)
import re
lines = [l for l in s.splitlines() if 'ATOMS' in l or 'CAS' in l]
print(len(lines)); print("\n".join(lines[:6]))
cfg = {'k32s4':(32,4),'k32s4r':(32,4),'k64s8':(64,8),'k64s8r':(64,8)}
ks = {n: bp.cuda_kernel(SRC, n) for n in cfg}
for k in ks.values(): k.set_smem(227*1024)
def smem(name, M):
    BN,SP = cfg[name]; KC=2048//SP
    return M*(KC+8)*2 + M*(BN+4)*4
torch.manual_seed(0)
for M in [17,25,34,64,93,128,172]:
    A = torch.randn(M,2048,device='cuda',dtype=torch.half); B = torch.randn(5120,2048,device='cuda',dtype=torch.half)
    C = torch.empty(M,5120,device='cuda',dtype=torch.half)
    ref = A@B.T
    out = []
    for name,(BN,SP) in cfg.items():
        grid = (5120//BN*SP,)
        f = lambda A,B,C,name=name,BN=BN,SP=SP: ks[name](grid,(256,),A,B,C,M,smem=smem(name,M))
        if not name.endswith('r'):
            C.zero_(); f(A,B,C); torch.cuda.synchronize()
            err = (C.float()-ref.float()).abs().max().item()
        else: err=0
        tm = bp.harness_time(f,(A,B),(C,))
        out.append(f"{name} {tm:.2f}us err{err:.3f}")
    tc = bp.harness_time(lambda A,B,C: torch.mm(A,B.t(),out=C),(A,B),(C,))
    print(M, " | ".join(out), f"| cublas {tc:.2f}")

